        if (l === "ta") return "\u0BB5\u0BB0\u0BCD\u0B95\u0BCB\u0BA4\u0BCD\u0BA4\u0BAE\u0BAE\u0BCD (D1 \u0BAE\u0BB1\u0BCD\u0BB1\u0BC1\u0BAE\u0BCD D9 \u0B87\u0BB2\u0BCD \u0B92\u0BB0\u0BC7 \u0BB0\u0BBE\u0B9A\u0BBF)";
