// src/services/doshaEngine.ts
var DoshaEngine = class {
  static get rules() {
    return [
      new KujaDoshaRule(),
      new KalaSarpaDoshaRule(),
      new PitraDoshaRule(),
      new GrahanDoshaRule(),
      new ShaniDoshaRule()
    ];
  }
  static detectAllDoshas(chart, lang = "en") {
    return this.rules.map((rule) => rule.detect(chart, lang));
  }
};
